Here's a C++ program that uses a recursive function to generate the Fibonacci sequence, starting with two given integers as the first two sequence elements:

```cpp
#include <iostream>
#include <string>
#include <vector>

using namespace std;

void generateFibonacci(int a, int b, int n, vector<int>& seq) {
    if (n == 0) {
        return;
    }
    seq.push_back(a);
    generateFibonacci(b, a + b, n - 1, seq);
}

int main() {
    int a, b, n;
    cout << "Enter the first two integers: ";
    cin >> a >> b;
    cout << "Enter the number of sequence elements to generate: ";
    cin >> n;

    if (cin.fail()) {
        cerr << "Invalid input. Please enter numeric values." << endl;
        return 1;
    }

    if (a < 0 || b < 0) {
        cerr << "Invalid input. Both integers must be non-negative." << endl;
        return 1;
    }

    if (n <= 0) {
        cerr << "Invalid input. The number of sequence elements must be positive." << endl;
        return 1;
    }

    vector<int> seq;
    generateFibonacci(a, b, n, seq);

    cout << "The Fibonacci sequence is: ";
    for (int i = 0; i < n; i++) {
        cout << seq[i] << ", ";
    }
    cout << endl;

    return 0;
}
```

