Here's a Go program that parses a struct in a Go source file and generates an Avro schema from it. The program takes the name of the Go source file and the name of the struct as input, and outputs a file named `struct.avsc`.

```go
package main

import (
	"fmt"
	"io/ioutil"
	"regexp"
	"strings"

	"github.com/apache/avro/avro"
)

func main() {
	sourceFile := "path/to/your/go/source/file.go"
	structName := "YourStructName"
	outputFile := "struct.avsc"

	content, err := ioutil.ReadFile(sourceFile)
	if err != nil {
		fmt.Println("Error reading source file:", err)
		return
	}

	// Extract the struct definition from the Go source code
	re := regexp.MustCompile(`type (\w+) struct {`)
	match := re.FindStringSubmatch(string(content))
	if len(match) != 2 {
		fmt.Println("Error extracting struct definition from source file")
		return
	}

	structType := match[1]

	// Generate the Avro schema
	schema, err := avro.NewSchema(structType, nil)
	if err != nil {
		fmt.Println("Error generating Avro schema:", err)
		return
	}

	// Write the Avro schema to a file
	err = ioutil.WriteFile(outputFile, []byte(schema), 0644)
	if err != nil {
		fmt.Println("Error writing Avro schema to file:", err)
		return
	}

	fmt.Printf("Avro schema generated successfully and written to %s\n", outputFile)
}
```

Replace `"path/to/your/go/source/file.go"` with the path to your Go source file, and `"YourStructName"` with the name of the struct you want to convert. The program will generate an Avro schema named `struct.avsc` in the

