Here's a simple C function that converts an array of command-line arguments (`argv`) to a null-terminated string:

```c
#include <stdio.h>
#include <stdlib.h>

char *argv_to_str(int argc, char **argv) {
    char *str = malloc(argc * sizeof(char *));
    if (str == NULL) {
        fprintf(stderr, "Error allocating memory for the string.\n");
        return NULL;
    }

    int i = 0;
    for (; i < argc; i++) {
        strcat(str, argv[i]);
        strcat(str, " ");
    }

    str[strlen(str) - 1] = '\0'; // Remove the last space character

    return str;
}

int main(int argc, char **argv) {
    char *str = argv_to_str(argc, argv);
    if (str != NULL) {
        printf("Converted string: %s\n", str);
        free(str);
    }

    return 0;
}
```

This function takes two arguments: `argc` (the number of command-line arguments) and `argv` (an array of pointers to the command-line arguments). It allocates memory for a string, iterates through the `argv` array, concatenates each argument with a space character, and finally returns the resulting string. The `main` function demonstrates how to use this function.

