Here's a simple decorator for Nest.js middleware that checks the `NODE_ENV` variable and returns `false` if it's not equal to `true`. You can use this decorator to wrap around any middleware function you want to apply this logic to.

```typescript
import { createParamDecorator, ExecutionContext } from '@nestjs/common';

export const IsProduction = createParamDecorator(
  (data: unknown, ctx: ExecutionContext) => {
    const request = ctx.switchToHttp().getRequest();
    return request.app.get('env') === 'production';
  },
);

export function ProductionMiddleware(middleware: Function) {
  return async (req, res, next) => {
    if (!IsProduction()) {
      return false;
    }

    await middleware(req, res, next);
  };
}
```

To use this decorator, simply wrap your middleware function with the `ProductionMiddleware` function:

```typescript
@UseGuards(ProductionMiddleware)
async someControllerAction(req, res, next) {
  // Your controller action code here
}
```

This will ensure that the middleware function is only executed when the `NODE_ENV` variable is set to `production`.

